#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)";cd "$ROOT";export JAVA_HOME="${JAVA_HOME:-${JAVA_HOME_17_X64:-}}";: "${ZUNGUN_PILOT_TOKEN:?required}"
ORIGIN="${ZUNGUN_ORIGIN:-https://zungun.simondalmasso44.workers.dev}"
OUT="${ORDER083_FIELD_RECOVERY_EVIDENCE:-$ROOT/evidence/order083/field-recovery}";mkdir -p "$OUT";GRADLE=(android/gradle/bootstrap-gradle.sh -p android --no-daemon --stacktrace);"${GRADLE[@]}" :app:assembleDebug :app:assembleDebugAndroidTest
adb install -r android/app/build/outputs/apk/debug/app-debug.apk >/dev/null;adb install -r android/app/build/outputs/apk/androidTest/debug/app-debug-androidTest.apk >/dev/null;RUNNER='com.zungun.app.test/androidx.test.runner.AndroidJUnitRunner'
run(){ local test="$1";adb shell am instrument -w -r -e class "com.zungun.app.Order083FieldRecoveryInstrumentedTest#$test" "$RUNNER" | tee "$OUT/$test.log";grep -q 'OK (1 test)' "$OUT/$test.log"; }
prepare_outage_control(){ local root_output;root_output="$(adb root 2>&1 || true)";printf '%s\n' "$root_output" > "$OUT/adb-root.txt";grep -qi 'cannot run as root' "$OUT/adb-root.txt" && { echo 'ADB_ROOT_REQUIRED_FOR_APPLICATION_TRAFFIC_OUTAGE' >&2;return 1; };timeout 30s adb wait-for-device;test "$(adb shell id -u 2>/dev/null|tr -d '\r')" = 0 || { echo 'ADB_ROOT_NOT_ACTIVE' >&2;return 1; };IPT="$(adb shell 'command -v iptables' 2>/dev/null|tr -d '\r')";test -n "$IPT" || { echo 'IPTABLES_NOT_AVAILABLE' >&2;return 1; };IP6T="$(adb shell 'command -v ip6tables' 2>/dev/null|tr -d '\r' || true)";printf '%s\n' "$IPT" > "$OUT/iptables-path.txt";printf '%s\n' "${IP6T:-NONE}" > "$OUT/ip6tables-path.txt"; }
delete_rule(){ local bin="$1" chain="$2";[[ -z "$bin" ]]&&return 0;adb shell "$bin -D OUTPUT -j $chain" >/dev/null 2>&1||true;adb shell "$bin -F $chain" >/dev/null 2>&1||true;adb shell "$bin -X $chain" >/dev/null 2>&1||true; }
restore_network(){ delete_rule "${IPT:-}" ZUNGUN083;delete_rule "${IP6T:-}" ZUNGUN083; }
install_block(){ local bin="$1";[[ -z "$bin" ]]&&return 0;adb shell "$bin -N ZUNGUN083" >/dev/null 2>&1||adb shell "$bin -F ZUNGUN083" >/dev/null;adb shell "$bin -A ZUNGUN083 -p tcp --dport 443 -j REJECT" >/dev/null;adb shell "$bin -I OUTPUT 1 -j ZUNGUN083" >/dev/null; }
off(){ local label="$1";restore_network;install_block "$IPT";install_block "${IP6T:-}";run phaseTrafficProbeOffline;printf 'APPLICATION_TRAFFIC_OUTAGE=PROVEN\nLABEL=%s\n' "$label" > "$OUT/traffic-$label-offline.txt"; }
on(){ local label="$1";restore_network;run phaseTrafficProbeOnline;printf 'APPLICATION_TRAFFIC_RECOVERY=PROVEN\nLABEL=%s\n' "$label" > "$OUT/traffic-$label-online.txt"; }
diagnostics(){ local op="$1" file="$2";curl --fail --silent --show-error -H "x-zungun-order083-key: $ZUNGUN_PILOT_TOKEN" "$ORIGIN/api/v1/_order083/diagnostics/$op" | tee "$file"; }
prepare_outage_control;trap restore_network EXIT INT TERM
run phaseTrafficProbeOnline
run phase1SetupOnline;off offline-b;run phase2QueueOffline;OP_B="$(adb shell run-as com.zungun.app cat files/order083-b-operation-id.txt | tr -d '\r\n')";test -n "$OP_B";adb shell am force-stop com.zungun.app;printf 'PROCESS_DEATH_AFTER_PROVEN_NOT_SENT=PROVEN\nOPERATION_ID=%s\n' "$OP_B" > "$OUT/process-death-after-proven-not-sent.txt";restore_network;diagnostics "$OP_B" "$OUT/b-before-recovery.json";jq -e '.fieldOperationCount==0 and .fieldEffectCount==0' "$OUT/b-before-recovery.json" >/dev/null;on online-b;adb shell monkey -p com.zungun.app -c android.intent.category.LAUNCHER 1 >/dev/null;sleep 2;run phase3VerifyRecovered;diagnostics "$OP_B" "$OUT/b-after-recovery.json";jq -e '.fieldOperationCount==1 and .fieldEffectCount==1' "$OUT/b-after-recovery.json" >/dev/null
run phase4SetupAmbiguousOnline;off offline-c;run phase5QueueAmbiguousOffline;OP="$(adb shell run-as com.zungun.app cat files/order083-ambiguous-operation-id.txt | tr -d '\r\n')";test -n "$OP";diagnostics "$OP" "$OUT/c-before-fault.json";jq -e '.fieldOperationCount==0 and .fieldEffectCount==0' "$OUT/c-before-fault.json" >/dev/null;node tools/order083/set-pilot-fault.mjs "$OP" | tee "$OUT/fault.json";on online-c;run phase6ObserveDurableUnknown;adb shell am force-stop com.zungun.app;printf 'PROCESS_DEATH_AFTER_UNKNOWN=PROVEN\nOPERATION_ID=%s\n' "$OP" > "$OUT/process-death-after-unknown.txt";adb shell monkey -p com.zungun.app -c android.intent.category.LAUNCHER 1 >/dev/null;sleep 2;run phase7VerifyUnknownThenReconciled;diagnostics "$OP" "$OUT/c-after-reconciliation.json";jq -e '.fieldOperationCount==1 and .fieldEffectCount==1' "$OUT/c-after-reconciliation.json" >/dev/null
trap - EXIT INT TERM;restore_network
printf '{"ok":true,"fieldOfflineForceStopRecovery":true,"provenNotSentBeforeBProcessDeath":true,"backendZeroBeforeBRecovery":true,"prefaultNotSentC":true,"backendZeroBeforeCFault":true,"ambiguousUnknownObserved":true,"processDeathAfterUnknown":true,"reconcileBeforeRetry":true,"backendExactlyOneAfterRecovery":true,"duplicateEffect":0,"outageOracle":"APPLICATION_TRAFFIC_HTTPS","outageControl":"ROOT_IPTABLES_TCP_443_REJECT","outageRequiresAdbRoot":true,"offlineAssertion":"REAL_APP_HTTP_FAILURE","recoveryAssertion":"REAL_APP_HTTP_SUCCESS","probeTimeoutSeconds":3}\n' > "$OUT/result.json"
